import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";

const args = Object.fromEntries(
  process.argv.slice(2).reduce((pairs, value, index, values) => {
    if (value.startsWith("--")) {
      pairs.push([value.slice(2), values[index + 1]]);
    }
    return pairs;
  }, [])
);

const nodeModules = resolve(args["node-modules"] || "vendor/node_modules");
const output = resolve(args.output || "MERMAID-THIRD-PARTY-NOTICES.txt");
const rootPackage = join(nodeModules, "mermaid", "package.json");
if (!existsSync(rootPackage)) {
  throw new Error(`Mermaid package not found at ${rootPackage}`);
}

function packageDirectory(name, fromDirectory) {
  let current = fromDirectory;
  while (true) {
    const candidate = join(current, "node_modules", name, "package.json");
    if (existsSync(candidate)) return dirname(candidate);
    const parent = dirname(current);
    if (parent === current) break;
    current = parent;
  }
  const fallback = join(nodeModules, name, "package.json");
  return existsSync(fallback) ? dirname(fallback) : null;
}

function licenseText(directory) {
  for (const filename of [
    "LICENSE",
    "LICENSE.md",
    "LICENSE.txt",
    "LICENCE",
    "LICENCE.md",
    "COPYING",
  ]) {
    const candidate = join(directory, filename);
    if (existsSync(candidate)) {
      return readFileSync(candidate, "utf8").trim();
    }
  }
  return "No standalone license text was present in the installed package.";
}

const mermaidDirectory = dirname(rootPackage);
const mermaid = JSON.parse(readFileSync(rootPackage, "utf8"));
const queue = Object.keys(mermaid.dependencies || {}).map((name) => ({
  name,
  from: mermaidDirectory,
}));
const packages = new Map();

while (queue.length > 0) {
  const { name, from } = queue.shift();
  const directory = packageDirectory(name, from);
  if (!directory) {
    throw new Error(`Unable to resolve Mermaid runtime dependency ${name}`);
  }
  const metadata = JSON.parse(
    readFileSync(join(directory, "package.json"), "utf8")
  );
  const key = `${metadata.name}@${metadata.version}`;
  if (packages.has(key)) continue;
  packages.set(key, {
    name: metadata.name,
    version: metadata.version,
    license:
      typeof metadata.license === "string"
        ? metadata.license
        : JSON.stringify(metadata.license || "UNKNOWN"),
    directory,
  });
  for (const dependency of Object.keys(metadata.dependencies || {})) {
    queue.push({ name: dependency, from: directory });
  }
}

const sorted = Array.from(packages.values()).sort((a, b) =>
  `${a.name}@${a.version}`.localeCompare(`${b.name}@${b.version}`)
);
const lines = [
  "MERMAID MODULAR ESM — TRANSITIVE THIRD-PARTY NOTICES",
  "",
  "Generated by scripts/vendor_web_assets.sh from Mermaid's installed runtime dependency graph.",
  "Only application runtime dependencies are included; build and test dependencies are excluded.",
  "",
  "PACKAGES",
  "",
];

for (const entry of sorted) {
  lines.push(
    `- ${entry.name} ${entry.version} — ${entry.license}`,
    `  Source: https://www.npmjs.com/package/${encodeURIComponent(entry.name)}/v/${entry.version}`
  );
}

for (const entry of sorted) {
  lines.push(
    "",
    "=".repeat(78),
    `${entry.name} ${entry.version} — ${entry.license}`,
    "=".repeat(78),
    "",
    licenseText(entry.directory)
  );
}

writeFileSync(output, `${lines.join("\n")}\n`);
console.log(`  Mermaid transitive notices: ${sorted.length} packages`);
